{"content":""""Robust meeting scheduler for Engineering, Design and Product teams.

Searches Feb 5-9, 2024 (Mon-Fri) for the earliest valid 2-hour slot in UTC.
"""

import os
import re
import uuid
from datetime import datetime, timedelta, timezone


def _parse_ics_datetime(value, params=""):
    """Parse an ICS date/datetime value into an aware UTC datetime."""
    value = value.strip()
    # DATE-only (VALUE=DATE or YYYYMMDD)
    if re.fullmatch(r"\d{8}", value):
        dt = datetime.strptime(value, "%Y%m%d").replace(tzinfo=timezone.utc)
        return dt, True
    # Strip fractional seconds if present: 20240205T093000.000Z
    m = re.fullmatch(
        r"(\d{8}T\d{6})(?:\.\d+)?(Z)?", value
    )
    if m:
        core, zulu = m.group(1), m.group(2)
        dt = datetime.strptime(core, "%Y%m%dT%H%M%S")
        # Floating times and TZID times are treated as UTC per task
        # (all times must be handled in UTC).
        dt = dt.replace(tzinfo=timezone.utc)
        return dt, False
    # Basic date-time without seconds: 20240205T0930Z (rare, be lenient)
    m2 = re.fullmatch(r"(\d{8}T\d{4})(Z)?", value)
    if m2:
        core = m2.group(1)
        dt = datetime.strptime(core, "%Y%m%dT%H%M").replace(tzinfo=timezone.utc)
        return dt, False
    raise ValueError(f"Unsupported ICS datetime value: {value!r}")


def _parse_duration(value):
    """Parse a subset of ISO8601 durations (e.g. PT2H, PT90M, P1DT2H)."""
    value = value.strip()
    m = re.fullmatch(
        r"P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?", value
    )
    if not m or value == "P":
        raise ValueError(f"Unsupported DURATION value: {value!r}")
    days = int(m.group(1) or 0)
    hours = int(m.group(2) or 0)
    minutes = int(m.group(3) or 0)
    seconds = int(m.group(4) or 0)
    return timedelta(days=days, hours=hours, minutes=minutes, seconds=seconds)


def parse_ics_file(path):
    """Parse DTSTART/DTEND (or DURATION) from every VEVENT in an ICS file."""
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        raw = f.read()
    # Unfold RFC5545 folded lines (CRLF followed by single space/tab).
    raw = raw.replace("\r\n", "\n")
    lines = []
    for line in raw.split("\n"):
        if line.startswith((" ", "\t")) and lines:
            lines[-1] += line[1:]
        else:
            lines.append(line)
    events = []
    in_event = False
    props = {}
    for line in lines:
        s = line.strip()
        if s == "BEGIN:VEVENT":
            in_event = True
            props = {}
        elif s == "END:VEVENT":
            if in_event:
                try:
                    start = end = None
                    is_date_only = False
                    if "DTSTART" in props:
                        start, is_date_only = _parse_ics_datetime(
                            props["DTSTART"][1], props["DTSTART"][0]
                        )
                    if "DTEND" in props:
                        end, _ = _parse_ics_datetime(
                            props["DTEND"][1], props["DTEND"][0]
                        )
                    elif "DURATION" in props and start is not None:
                        end = start + _parse_duration(props["DURATION"][1])
                    if start is not None and end is not None:
                        if is_date_only and "DTEND" not in props:
                            # All-day single DATE: block the whole day.
                            end = start + timedelta(days=1)
                        if end.tzinfo is None:
                            end = end.replace(tzinfo=timezone.utc)
                        if start.tzinfo is None:
                            start = start.replace(tzinfo=timezone.utc)
                        start = start.astimezone(timezone.utc)
                        end = end.astimezone(timezone.utc)
                        if end > start:
                            events.append((start, end))
                except ValueError:
                    continue
            in_event = False
            props = {}
        elif in_event and ":" in s:
            left, _, val = s.partition(":")
            name = left.split(";")[0].strip().upper()
            if name in ("DTSTART", "DTEND", "DURATION"):
                props[name] = (left, val.strip())
    return events


def _overlaps(a_start, a_end, b_start, b_end):
    """Half-open overlap check: [a_start, a_end) vs [b_start, b_end)."""
    return a_start < b_end and b_start < a_end


class MeetingScheduler:
    """Find the earliest valid 2-hour Project Kickoff slot, Feb 5-9 2024."""

    MEETING_MINUTES = 120
    SEARCH_START = datetime(2024, 2, 5, tzinfo=timezone.utc)
    SEARCH_END = datetime(2024, 2, 9, 23, 59, 59, tzinfo=timezone.utc)

    def __init__(self):
        self.eng_busy = []
        self.design_busy = []
        self.prod_busy = []
        self.slot_start = None
        self.slot_end = None

    def load_calendars(self, eng_path, design_path, prod_path):
        """Parse the ICS files at the given paths."""
        self.eng_busy = parse_ics_file(eng_path) if os.path.exists(eng_path) else []
        self.design_busy = (
            parse_ics_file(design_path) if os.path.exists(design_path) else []
        )
        self.prod_busy = (
            parse_ics_file(prod_path) if os.path.exists(prod_path) else []
        )

    def _slot_valid(self, start, end):
        day = start.date()
        # Work-hour windows (all UTC).
        eng_open = datetime(day.year, day.month, day.day, 8, 0, tzinfo=timezone.utc)
        eng_close = datetime(day.year, day.month, day.day, 16, 0, tzinfo=timezone.utc)
        design_open = datetime(day.year, day.month, day.day, 9, 0, tzinfo=timezone.utc)
        design_close = datetime(day.year, day.month, day.day, 17, 0, tzinfo=timezone.utc)
        prod_open = datetime(day.year, day.month, day.day, 8, 0, tzinfo=timezone.utc)
        prod_close = datetime(day.year, day.month, day.day, 17, 0, tzinfo=timezone.utc)

        # Must fit inside every team's work hours.
        if not (eng_open <= start and end <= eng_close):
            return False
        if not (design_open <= start and end <= design_close):
            return False
        if not (prod_open <= start and end <= prod_close):
            return False
        # Product morning block: cannot meet before 09:00.
        morning = datetime(day.year, day.month, day.day, 9, 0, tzinfo=timezone.utc)
        if start < morning:
            return False

        # Lunch breaks: Eng 12:00-12:30, Design 12:00-13:00 (union 12:00-13:00).
        eng_lunch_s = datetime(day.year, day.month, day.day, 12, 0, tzinfo=timezone.utc)
        eng_lunch_e = datetime(day.year, day.month, day.day, 12, 30, tzinfo=timezone.utc)
        des_lunch_s = datetime(day.year, day.month, day.day, 12, 0, tzinfo=timezone.utc)
        des_lunch_e = datetime(day.year, day.month, day.day, 13, 0, tzinfo=timezone.utc)
        if _overlaps(start, end, eng_lunch_s, eng_lunch_e):
            return False
        if _overlaps(start, end, des_lunch_s, des_lunch_e):
            return False

        # Existing meetings: no overlap for any team.
        for b_s, b_e in self.eng_busy:
            if _overlaps(start, end, b_s, b_e):
                return False
        for b_s, b_e in self.design_busy:
            if _overlaps(start, end, b_s, b_e):
                return False
        # Product: no overlap + 20-min buffer after any existing meeting.
        buf = timedelta(minutes=20)
        for b_s, b_e in self.prod_busy:
            if _overlaps(start, end, b_s, b_e):
                return False
            if b_e <= start < b_e + buf:
                return False
        return True

    def find_slot(self):
        """Execute the search logic satisfying all constraints.

        Priority 1 (Tue/Wed/Thu) is searched before Priority 2 (Mon/Fri).
        Within each priority group days are chronological and within each
        day the earliest start time wins (1-minute granularity).
        Returns (start, end) as aware UTC datetimes, or None if no slot.
        """
        duration = timedelta(minutes=self.MEETING_MINUTES)
        # Priority 1: Tue 6th, Wed 7th, Thu 8th; Priority 2: Mon 5th, Fri 9th.
        ordered_days = [
            datetime(2024, 2, 6, tzinfo=timezone.utc),
            datetime(2024, 2, 7, tzinfo=timezone.utc),
            datetime(2024, 2, 8, tzinfo=timezone.utc),
            datetime(2024, 2, 5, tzinfo=timezone.utc),
            datetime(2024, 2, 9, tzinfo=timezone.utc),
        ]
        for day in ordered_days:
            day_start = datetime(day.year, day.month, day.day, 9, 0, tzinfo=timezone.utc)
            latest_start = datetime(
                day.year, day.month, day.day, 14, 0, tzinfo=timezone.utc
            )
            cursor = day_start
            while cursor <= latest_start:
                end = cursor + duration
                if self._slot_valid(cursor, end):
                    self.slot_start = cursor
                    self.slot_end = end
                    return (self.slot_start, self.slot_end)
                cursor += timedelta(minutes=1)
        self.slot_start = None
        self.slot_end = None
        return None

    def save_ics(self, output_path):
        """Generate the result file in RFC 5545 format."""
        if self.slot_start is None or self.slot_end is None:
            result = self.find_slot()
            if result is None:
                raise ValueError("No valid slot found; cannot write ICS file.")
        fmt = "%Y%m%dT%H%M%SZ"
        dtstamp = datetime.now(timezone.utc).strftime(fmt)
        uid = f"{uuid.uuid4()}@meetingscheduler"
        lines = [
            "BEGIN:VCALENDAR",
            "VERSION:2.0",
            "PRODID:-//MeetingScheduler//EN",
            "BEGIN:VEVENT",
            f"UID:{uid}",
            f"DTSTAMP:{dtstamp}",
            f"DTSTART:{self.slot_start.strftime(fmt)}",
            f"DTEND:{self.slot_end.strftime(fmt)}",
            "SUMMARY:Project Kickoff Meeting",
            "END:VEVENT",
            "END:VCALENDAR",
        ]
        with open(output_path, "w", encoding="utf-8", newline="") as f:
            f.write("\r\n".join(lines) + "\r\n")
        return output_path


if __name__ == "__main__":
    base = os.path.dirname(os.path.abspath(__file__))
    sched = MeetingScheduler()
    sched.load_calendars(
        os.path.join(base, "engineering_calendar.ics"),
        os.path.join(base, "design_calendar.ics"),
        os.path.join(base, "product_calendar.ics"),
    )
    slot = sched.find_slot()
    if slot is None:
        raise SystemExit("No valid slot found between Feb 5-9, 2024.")
    print(f"Scheduled: {slot[0].isoformat()} -> {slot[1].isoformat()}")
    sched.save_ics("/app/meeting_scheduled.ics")
    print("Wrote /app/meeting_scheduled.ics")
